sp_widget.client_script:
api.controller = function($scope, $http, spUtil, $rootScope) {
  var c = this;

  // Unified Theme System
  var savedTheme = localStorage.getItem('edusphere_theme') || 'dark';
  c.currentTheme = savedTheme;
  document.documentElement.setAttribute('data-theme', savedTheme);
  document.body.setAttribute('data-theme', savedTheme);

  c.toggleTheme = function() {
    c.currentTheme = (c.currentTheme == 'dark') ? 'light' : 'dark';
    localStorage.setItem('edusphere_theme', c.currentTheme);
    document.documentElement.setAttribute('data-theme', c.currentTheme);
    document.body.setAttribute('data-theme', c.currentTheme);
    $rootScope.$broadcast('edusphere:theme_changed', c.currentTheme);
  };

  $scope.$on('edusphere:theme_changed', function(ev, theme) {
    c.currentTheme = theme;
    document.documentElement.setAttribute('data-theme', theme);
    document.body.setAttribute('data-theme', theme);
  });

  c.reg = {
    first_name: '',
    last_name: '',
    email: '',
    mobile: '',
    terms: false
  };
  c.isSubmitting = false;
  c.submittedSuccess = false;
  c.errorMessage = '';

  c.submitRegistration = function() {
    c.errorMessage = '';
    if (!c.reg.first_name || !c.reg.last_name || !c.reg.email) {
      c.errorMessage = 'Please complete all required fields.';
      return;
    }
    if (!c.reg.terms) {
      c.errorMessage = 'Please review and accept the admission regulations and terms.';
      return;
    }

    c.isSubmitting = true;
    c.server.get({
      action: 'submit_registration',
      first_name: c.reg.first_name,
      last_name: c.reg.last_name,
      email: c.reg.email,
      mobile: c.reg.mobile
    }).then(function(response) {
      c.isSubmitting = false;
      if (response.data && response.data.success) {
        c.submittedSuccess = true;
      } else {
        c.errorMessage = (response.data && response.data.message) || 'Registration failed. Please try again.';
      }
    }, function(err) {
      c.isSubmitting = false;
      c.errorMessage = 'Network error during registration. Please verify connection and retry.';
    });
  };
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

.edu-reg-root {
  min-height: 100vh;
  background-color: #070b14;
  color: #f1f5f9;
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  position: relative;
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
}

/* NAVBAR */
.edu-nav {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(10, 15, 29, 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(51, 65, 85, 0.4);
}
.edu-nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0.85rem 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.edu-nav-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
  font-weight: 700;
  font-size: 1.15rem;
  color: #ffffff;
}
.edu-nav-logo-img {
  width: 36px;
  height: 36px;
  object-fit: contain;
}
.edu-nav-links {
  display: flex;
  gap: 1.25rem;
}
.edu-nav-link {
  color: #94a3b8;
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
  transition: color 0.2s;
}
.edu-nav-link:hover {
  color: #C2882F;
}

/* BACKGROUND ORBS */
.edu-reg-body {
  flex: 1;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 3rem 1.5rem;
}
.edu-reg-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(100px);
  pointer-events: none;
  z-index: 0;
}
.edu-reg-orb-1 {
  width: 450px;
  height: 450px;
  background: rgba(99, 102, 241, 0.12);
  top: 10%;
  left: 20%;
}
.edu-reg-orb-2 {
  width: 380px;
  height: 380px;
  background: rgba(194, 136, 47, 0.12);
  bottom: 10%;
  right: 20%;
}

/* CARD */
.edu-reg-card {
  position: relative;
  z-index: 10;
  width: 100%;
  max-width: 540px;
  background: rgba(15, 23, 42, 0.88);
  border: 1px solid rgba(51, 65, 85, 0.6);
  border-radius: 1.25rem;
  padding: 2.5rem;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(16px);
}

.edu-reg-header {
  text-align: center;
  margin-bottom: 2rem;
}
.edu-reg-logo-box {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 72px;
  height: 72px;
  background: rgba(194, 136, 47, 0.1);
  border: 1px solid rgba(194, 136, 47, 0.3);
  border-radius: 1rem;
  margin-bottom: 1rem;
}
.edu-reg-logo {
  width: 48px;
  height: 48px;
  object-fit: contain;
}
.edu-badge-reg {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 0.85rem;
  border-radius: 9999px;
  background: rgba(16, 185, 129, 0.12);
  border: 1px solid rgba(16, 185, 129, 0.3);
  color: #34d399;
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: 0.85rem;
}
.edu-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #10b981;
}
.edu-reg-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: #ffffff;
  margin: 0 0 0.5rem 0;
}
.edu-reg-subtitle {
  font-size: 0.95rem;
  color: #94a3b8;
  line-height: 1.5;
  margin: 0;
}

/* FORM FIELDS */
.edu-reg-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}
.edu-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}
@media (max-width: 500px) {
  .edu-form-row { grid-template-columns: 1fr; }
}

.edu-field-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.edu-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: #cbd5e1;
  margin: 0;
}
.edu-label .req {
  color: #f43f5e;
}
.edu-hint {
  font-size: 0.75rem;
  color: #64748b;
  margin-top: 0.2rem;
}

.edu-input-icon-wrap {
  position: relative;
  display: flex;
  align-items: center;
}
.edu-field-icon {
  position: absolute;
  left: 0.9rem;
  color: #64748b;
  pointer-events: none;
}
.edu-input {
  width: 100%;
  background: rgba(30, 41, 59, 0.7);
  border: 1px solid #334155;
  border-radius: 0.65rem;
  padding: 0.75rem 1rem;
  font-size: 0.95rem;
  color: #ffffff;
  outline: none;
  transition: all 0.2s;
  box-sizing: border-box;
}
.edu-input-with-icon {
  padding-left: 2.6rem;
}
.edu-input:focus {
  border-color: #C2882F;
  box-shadow: 0 0 0 3px rgba(194, 136, 47, 0.2);
  background: rgba(30, 41, 59, 0.95);
}

/* TERMS */
.edu-terms-wrap {
  margin-top: 0.25rem;
}
.edu-checkbox-label {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  font-size: 0.825rem;
  color: #94a3b8;
  line-height: 1.4;
  cursor: pointer;
}
.edu-checkbox-label input {
  margin-top: 0.2rem;
  accent-color: #C2882F;
}
.edu-checkbox-label a {
  color: #C2882F;
  text-decoration: underline;
}

/* BUTTON */
.edu-btn-reg-submit {
  width: 100%;
  padding: 0.9rem 1.5rem;
  background: linear-gradient(135deg, #C2882F 0%, #a46d1b 100%);
  border: none;
  border-radius: 0.65rem;
  color: #ffffff;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 4px 15px rgba(194, 136, 47, 0.35);
  transition: all 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 0.5rem;
}
.edu-btn-reg-submit:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(194, 136, 47, 0.5);
  background: linear-gradient(135deg, #d39535 0%, #b87b22 100%);
}
.edu-btn-reg-submit:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.edu-spinner {
  animation: spin 1s linear infinite;
  display: inline-block;
  vertical-align: middle;
  margin-right: 0.5rem;
}
@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.edu-reg-footer-links {
  text-align: center;
  margin-top: 1.25rem;
  font-size: 0.9rem;
  color: #94a3b8;
}
.edu-link-gold {
  color: #C2882F;
  font-weight: 600;
  text-decoration: none;
  margin-left: 0.35rem;
}
.edu-link-gold:hover {
  text-decoration: underline;
}

/* ALERT */
.edu-reg-alert {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.85rem 1rem;
  background: rgba(239, 68, 68, 0.15);
  border: 1px solid rgba(239, 68, 68, 0.4);
  border-radius: 0.65rem;
  color: #fca5a5;
  font-size: 0.875rem;
  margin-bottom: 1.25rem;
}

/* SUCCESS STATE */
.edu-reg-success {
  text-align: center;
  padding: 1rem 0;
}
.edu-success-icon-wrap {
  width: 72px;
  height: 72px;
  margin: 0 auto 1.25rem;
  background: rgba(16, 185, 129, 0.12);
  border: 1px solid rgba(16, 185, 129, 0.3);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.edu-success-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #ffffff;
  margin: 0 0 0.5rem 0;
}
.edu-success-desc {
  font-size: 0.95rem;
  color: #94a3b8;
  margin: 0 0 0.75rem 0;
}
.edu-email-pill {
  display: inline-block;
  padding: 0.4rem 1.2rem;
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid #334155;
  border-radius: 9999px;
  font-size: 0.95rem;
  font-weight: 600;
  color: #38bdf8;
  margin-bottom: 1.25rem;
}
.edu-success-notice {
  background: rgba(99, 102, 241, 0.1);
  border: 1px solid rgba(99, 102, 241, 0.3);
  border-radius: 0.65rem;
  padding: 0.85rem 1rem;
  font-size: 0.85rem;
  color: #cbd5e1;
  text-align: left;
  line-height: 1.5;
  margin-bottom: 1.5rem;
}
.edu-success-actions {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.edu-btn-reg-primary {
  display: block;
  padding: 0.85rem 1.5rem;
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  border-radius: 0.65rem;
  color: #ffffff;
  font-size: 0.95rem;
  font-weight: 700;
  text-decoration: none;
  box-shadow: 0 4px 15px rgba(16, 185, 129, 0.3);
  transition: all 0.2s;
}
.edu-btn-reg-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(16, 185, 129, 0.45);
}
.edu-btn-reg-ghost {
  display: block;
  padding: 0.75rem 1.5rem;
  color: #94a3b8;
  font-size: 0.9rem;
  text-decoration: none;
  transition: color 0.2s;
}
.edu-btn-reg-ghost:hover {
  color: #ffffff;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-in {
  animation: fadeIn 0.3s ease-out forwards;
}


/* Explicit logo sizing constraint */
.edu-nav-logo-img {
  width: 44px !important;
  height: 44px !important;
  max-width: 44px !important;
  max-height: 44px !important;
  min-width: 44px !important;
  min-height: 44px !important;
  object-fit: contain !important;
  display: inline-block !important;
  vertical-align: middle !important;
}
.edu-footer-brand .edu-nav-logo-img {
  width: 36px !important;
  height: 36px !important;
  max-width: 36px !important;
  max-height: 36px !important;
}


/* ==========================================================================
   SELF-REGISTRATION TYPOGRAPHY, INPUT SIZES & BADGE POSITIONING ENHANCEMENTS
   ========================================================================== */
