}

.edu-input-with-icon {
  padding-left: 3rem !important;
}

.edu-field-icon {
  left: 1.05rem !important;
  width: 20px !important;
  height: 20px !important;
  color: #94a3b8 !important;
}

.edu-field-group {
  gap: 0.5rem !important;
